import { Component, inject, signal } from '@angular/core';
import { Location } from '@angular/common';
import { HttpClient, provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { provideRouter, Router, Routes, ActivatedRoute } from '@angular/router';
import { RouterTestingHarness } from '@angular/router/testing';
import { timeout } from 'rxjs';

@Component({
  template: `@if (state() === 'loading') { <p>Cargando</p> } @if (state() === 'error') { <p role="alert">Error</p> } @if (state() === 'ok') { <h1 tabindex="-1">Hola {{ data() }}</h1> }`,
})
class Demo {
  private readonly http = inject(HttpClient);
  state = signal<'loading' | 'ok' | 'error'>('loading');
  data = signal('');
  constructor() {
    this.http.get<{ v: string }>('/api/x?filters[a][$eq]=CO').pipe(timeout(10_000)).subscribe({
      next: (r) => { this.data.set(r.v); this.state.set('ok'); },
      error: () => this.state.set('error'),
    });
  }
}
@Component({ template: 'other' })
class Other {}

const routes: Routes = [{ path: 'a', component: Demo }, { path: 'b', component: Other }];

async function pump() {
  if (vi.isFakeTimers()) await vi.advanceTimersByTimeAsync(0);
  else await new Promise((r) => setTimeout(r, 0));
}
async function take(http: HttpTestingController) {
  for (let i = 0; i < 50; i++) {
    const [r] = http.match((q) => decodeURIComponent(q.urlWithParams).startsWith('/api/x'));
    if (r) return r;
    await pump();
  }
  throw new Error('no request');
}

describe('experiment', () => {
  beforeEach(() => {
    TestBed.configureTestingModule({ providers: [provideRouter(routes), provideHttpClient(), provideHttpClientTesting()] });
  });
  afterEach(() => vi.useRealTimers());

  it('real timers: flush, back', async () => {
    const http = TestBed.inject(HttpTestingController);
    const harness = await RouterTestingHarness.create();
    const nav = harness.navigateByUrl('/a');
    const req = await take(http);
    console.log('URL', decodeURIComponent(req.request.urlWithParams));
    req.flush({ v: 'x' });
    await nav;
    await harness.fixture.whenStable();
    expect(harness.fixture.nativeElement.textContent).toContain('Hola x');
    await harness.navigateByUrl('/b');
    expect(TestBed.inject(Location).path()).toBe('/b');
    TestBed.inject(Location).back();
    await harness.fixture.whenStable();
    await new Promise((r) => setTimeout(r, 0));
    await harness.fixture.whenStable();
    console.log('PATH', TestBed.inject(Location).path(), TestBed.inject(Router).url);
  });

  it('fake timers: timeout', async () => {
    vi.useFakeTimers();
    const http = TestBed.inject(HttpTestingController);
    const harness = await RouterTestingHarness.create();
    const nav = harness.navigateByUrl('/a');
    await take(http);
    await vi.advanceTimersByTimeAsync(10_000);
    await nav;
    await vi.advanceTimersByTimeAsync(0);
    expect(harness.fixture.nativeElement.textContent).toContain('Error');
  });
});

