      strapiListResponse([item({ key: 'a1', type: 'slider' }), item({ key: 'b2', label: '' }), item({ key: 'c3', type: 'select', options: [] })]),
    );
    expect(parsed).toEqual([]);
  });

  it.each([
    ['null', null],
    ['undefined', undefined],
    ['a string', 'not json'],
    ['an object without data', {}],
    ['a response whose data is not a list', { data: 'oops' }],
