    const lengthFirst = withRules('text', true, [
      { kind: 'minLength', value: 5, message: 'Mensaje de longitud.' },
      { kind: 'pattern', value: '^[0-9]+$', message: 'Mensaje de formato.' },
    ]);
    const patternFirst = withRules('text', true, [
      { kind: 'pattern', value: '^[0-9]+$', message: 'Mensaje de formato.' },
