    ]);
    expect(validateField(lengthFirst, 'ab', TODAY)).toBe('Mensaje de longitud.');
    expect(validateField(patternFirst, 'ab', TODAY)).toBe('Mensaje de formato.');
  });

  it('the required check comes before the rules', () => {
