import type { FieldConfig, FieldType, ValidationRule } from './field-config.model';
const TYPES = ['text', 'number', 'select', 'date', 'checkbox'];
const APPLIES: Record<string, string[]> = { minLength: ['text'], maxLength: ['text'], pattern: ['text'], rutCheckDigit: ['text'], min: ['number'], max: ['number'], yearRange: ['number'], minAge: ['date'] };
