    case 'minAge': if (!isInt(r['years'], 1)) return 'minAge needs years'; return { kind, years: r['years'], ...msg } as ValidationRule;
    case 'yearRange': if (!isInt(r['maxYearsOld'], 0) || !isInt(r['maxYearsAhead'], 0)) return 'yearRange needs params'; return { kind, maxYearsOld: r['maxYearsOld'], maxYearsAhead: r['maxYearsAhead'], ...msg } as ValidationRule;
