    const cfg: FieldConfig = { key, type: type as FieldType, label: raw['label'] as string, isRequired: raw['isRequired'] === true, sortOrder: raw['sortOrder'] as number, errorMessage: errorMessage as string, rules };
    for (const k of ['helpText', 'placeholder', 'requiredMessage'] as const) if (typeof raw[k] === 'string' && raw[k]) cfg[k] = raw[k] as string;
