  readonly step1Output = signal<Step1Output | null>(null);
  private memoryOnly = false;
  private warned = false;
  constructor() { this.read(); }
  private warnOnce(m: string) { if (!this.warned) { this.warned = true; console.warn(m); } }
  private read() {
    let raw: string | null = null;
    try { raw = sessionStorage.getItem(KEY); } catch { this.memoryOnly = true; this.warnOnce('sessionStorage unavailable'); return; }
    if (raw === null) return;
    try {
      const e = JSON.parse(raw);
      const ok = e && typeof e === 'object' && e.version === 1 && typeof e.country === 'string' && /^[A-Z]{2}$/.test(e.country) && e.step1 && typeof e.step1.values === 'object' && e.step1.values !== null && Object.values(e.step1.values).every((v) => typeof v === 'string' || typeof v === 'boolean');
