import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom, timeout } from 'rxjs';
import { parseFieldConfigs } from '../shared/field-config';
import type { FieldConfig } from '../shared/field-config.model';
export interface Country { code: string; name: string; currencyCode: string; locale: string; sortOrder: number }
@Injectable({ providedIn: 'root' })
export class CountryStore {
  private readonly http = inject(HttpClient);
  readonly countries = signal<Country[]>([]);
  readonly status = signal<'idle' | 'loading' | 'ready' | 'error'>('idle');
  private inflight?: Promise<void>;
  load(): Promise<void> {
    if (this.status() === 'ready') return Promise.resolve();
    if (this.inflight) return this.inflight;
    this.status.set('loading');
    this.inflight = firstValueFrom(this.http.get<{ data: Record<string, unknown>[] }>('/api/countries', { params: new HttpParams().set('sort', 'sortOrder:asc') }).pipe(timeout(10_000)))
      .then((r) => {
        const out: Country[] = [];
        for (const c of r.data ?? []) {
          if (typeof c['code'] === 'string' && /^[A-Z]{2}$/.test(c['code']) && typeof c['name'] === 'string' && c['name'] && typeof c['currencyCode'] === 'string' && /^[A-Z]{3}$/.test(c['currencyCode'])) out.push(c as unknown as Country);
          else console.warn(`Dropped country entry`);
        }
        this.countries.set(out); this.status.set('ready');
      })
      .catch(() => { this.status.set('error'); })
      .finally(() => { this.inflight = undefined; });
    return this.inflight;
  }
  retry(): Promise<void> { this.status.set('idle'); return this.load(); }
}
@Injectable({ providedIn: 'root' })
export class FieldsStore {
  private readonly http = inject(HttpClient);
  private readonly cache = new Map<string, FieldConfig[]>();
  async load(code: string): Promise<FieldConfig[]> {
    const hit = this.cache.get(code); if (hit) return hit;
    const params = new HttpParams().set('filters[country][code][$eq]', code).set('sort', 'sortOrder:asc').set('pagination[pageSize]', '100');
    const r = await firstValueFrom(this.http.get('/api/form-fields', { params }).pipe(timeout(10_000)));
    const parsed = parseFieldConfigs(r);
    if (!parsed.length) throw new Error('no fields');
    this.cache.set(code, parsed); return parsed;
  }
}
