import { Component, ElementRef, afterNextRender, inject, signal, computed, Injector, effect } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { CLOCK } from '../../core/clock';
import { CountryStore, FieldsStore } from '../../core/content';
import { QuoteStore } from '../../core/quote-store';
import type { FieldConfig } from '../../shared/field-config.model';
import { validateField } from '../../shared/field-validators';
import { hydrate } from '../../shared/field-values';

@Component({
  selector: 'app-quote-form-page',
  template: `
    <h1 tabindex="-1" #heading>Tus datos y los de tu vehículo</h1>
    @if (state() === 'loading') { <div aria-busy="true"><p aria-live="polite">Cargando formulario…</p></div> }
    @if (state() === 'error') {
      <p role="alert">No pudimos cargar el formulario. Intenta de nuevo.</p>
      <button type="button" #retry (click)="load()">Reintentar</button>
    }
    @if (state() === 'ready') {
      <p>Los campos marcados con * son obligatorios.</p>
      <form (submit)="$event.preventDefault(); submit()" novalidate>
        @for (f of fields(); track f.key) {
          <div>
            <label [for]="'f-' + f.key">{{ f.label }}@if (f.isRequired) { <span aria-hidden="true"> *</span> }</label>
            @switch (f.type) {
              @case ('select') {
                <select [id]="'f-' + f.key" [attr.aria-required]="f.isRequired" [attr.aria-invalid]="shown(f) ? 'true' : null" [attr.aria-describedby]="desc(f)"
                  (change)="set(f, $any($event.target).value)" (blur)="touch(f)">
                  <option value="" disabled [selected]="values()[f.key] === ''">Selecciona una opción</option>
                  @for (o of f.options; track o.value) { <option [value]="o.value" [selected]="values()[f.key] === o.value">{{ o.label }}</option> }
                </select>
              }
              @case ('checkbox') {
                <input type="checkbox" [id]="'f-' + f.key" [checked]="values()[f.key] === true" [attr.aria-required]="f.isRequired" [attr.aria-invalid]="shown(f) ? 'true' : null" [attr.aria-describedby]="desc(f)"
                  (change)="set(f, $any($event.target).checked)" (blur)="touch(f)" />
              }
              @default {
                <input [type]="f.type" [id]="'f-' + f.key" [value]="values()[f.key]" [attr.aria-required]="f.isRequired" [attr.aria-invalid]="shown(f) ? 'true' : null" [attr.aria-describedby]="desc(f)"
                  (input)="set(f, $any($event.target).value)" (blur)="touch(f)" />
              }
            }
            @if (f.helpText) { <small [id]="'h-' + f.key">{{ f.helpText }}</small> }
            @if (shown(f)) { <p [id]="'e-' + f.key" role="alert">{{ error(f) }}</p> }
          </div>
        }
        <button type="submit">Continuar</button>
      </form>
    }
  `,
})
export class QuoteFormPage {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly countries = inject(CountryStore);
  private readonly fieldsStore = inject(FieldsStore);
  private readonly quote = inject(QuoteStore);
  private readonly clock = inject(CLOCK);
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly injector = inject(Injector);
  readonly state = signal<'loading' | 'error' | 'ready'>('loading');
  readonly fields = signal<FieldConfig[]>([]);
  readonly values = signal<Record<string, string | boolean>>({});
  private readonly touched = signal<Record<string, boolean>>({});
  private code = '';

  constructor() { void this.load(); }

  async load(): Promise<void> {
    this.state.set('loading');
    await this.countries.load();
    const slug = (this.route.snapshot.paramMap.get('country') ?? this.route.snapshot.parent?.paramMap.get('country') ?? '').toLowerCase();
    this.code = this.countries.countries().find((c) => c.code.toLowerCase() === slug)?.code ?? slug.toUpperCase();
    try {
      const configs = await this.fieldsStore.load(this.code);
      this.quote.prune(configs);
      this.fields.set(configs);
      this.values.set(hydrate(configs, this.quote.values()));
      this.state.set('ready');
      this.focus('h1');
    } catch {
      this.state.set('error');
      this.focus('button');
    }
  }
  private focus(sel: string) { afterNextRender(() => (this.host.nativeElement.querySelector(sel) as HTMLElement | null)?.focus(), { injector: this.injector }); }
  set(f: FieldConfig, v: string | boolean) { this.values.update((x) => ({ ...x, [f.key]: v })); this.quote.setValue(f.key, v); }
  touch(f: FieldConfig) { this.touched.update((t) => ({ ...t, [f.key]: true })); }
  error(f: FieldConfig) { return validateField(f, this.values()[f.key], this.clock()); }
  shown(f: FieldConfig) { return !!this.touched()[f.key] && !!this.error(f); }
  desc(f: FieldConfig) { return [f.helpText ? 'h-' + f.key : '', this.shown(f) ? 'e-' + f.key : ''].filter(Boolean).join(' ') || null; }
  submit() {
    const configs = this.fields();
    this.touched.set(Object.fromEntries(configs.map((c) => [c.key, true])));
    const out = this.quote.completeStep1(configs);
    if (out) { void this.router.navigateByUrl(`/${this.code.toLowerCase()}/planes`); return; }
    const first = configs.find((c) => this.error(c));
    afterNextRender(() => (this.host.nativeElement.querySelector('#f-' + first?.key) as HTMLElement | null)?.focus(), { injector: this.injector });
  }
}
