                  (input)="set(f, $any($event.target).value)" (blur)="touch(f)" />
              }
            }
            @if (f.helpText) { <small [id]="'h-' + f.key">{{ f.helpText }}</small> }
            @if (shown(f)) { <p [id]="'e-' + f.key" role="alert">{{ error(f) }}</p> }
