  error(f: FieldConfig) { return validateField(f, this.values()[f.key], this.clock()); }
  shown(f: FieldConfig) { return !!this.touched()[f.key] && !!this.error(f); }
  desc(f: FieldConfig) { return [f.helpText ? 'h-' + f.key : '', this.shown(f) ? 'e-' + f.key : ''].filter(Boolean).join(' ') || null; }
  submit() {
    const configs = this.fields();
    this.touched.set(Object.fromEntries(configs.map((c) => [c.key, true])));
