import { Router, RouterLink } from '@angular/router';
import { CountryStore } from '../core/content';
@Component({
  selector: 'app-country-page', imports: [RouterLink],
  template: `
    @if (store.status() === 'loading') { <p aria-live="polite">Cargando…</p> }
    @if (store.status() === 'error') { <p role="alert">No pudimos cargar la lista de países. Intenta de nuevo.</p><button type="button" (click)="retry()">Reintentar</button> }
    @if (store.status() === 'ready') {
      @if (unknown) { <h1>Este país no está disponible.</h1> }
      @for (c of store.countries(); track c.code) { <a [routerLink]="['/', c.code.toLowerCase(), 'datos']">{{ c.name }}</a> }
    }
  `,
})
export class CountryPage {
  readonly store = inject(CountryStore);
  private readonly router = inject(Router);
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly injector = inject(Injector);
  readonly unknown = this.router.url !== '/';
  constructor() {
    void this.store.load();
    effect(() => { if (this.store.status() === 'error') afterNextRender(() => this.host.nativeElement.querySelector('button')?.focus(), { injector: this.injector }); });
  }
  async retry() { await this.store.retry(); if (this.router.url !== '/' && this.store.status() === 'ready') void this.router.navigateByUrl(this.router.url, { onSameUrlNavigation: 'reload' }); }
}
