import { defineConfig, devices } from '@playwright/test';

/**
 * E2E configuration for the wizard (CLAUDE.md section 4: @playwright/test, no schematics).
 *
 * The tests run against the docker compose stack with the seed (ADR-0002 topology): the `frontend`
 * nginx container serves the Angular build and proxies the read-only content API on one origin;
 * Strapi keeps its own port for the admin panel and for the Node-side test setup.
 * Nothing is mocked except where a test aborts a request in the browser on purpose (US-01-AC-17).
 *
 * Environment variables (none holds a default secret):
 *   E2E_BASE_URL          origin of the nginx front end           default http://localhost:8080
 *   E2E_STRAPI_URL        Strapi's own port (admin, direct reads) default http://localhost:1337
 *   STRAPI_ADMIN_EMAIL    development super admin (ADR-0002, US-01-AC-03 write flow only)
 *   STRAPI_ADMIN_PASSWORD   its password; set them in the git-ignored .env of the repository root
 */
try {
  // Node >= 20.12. A missing file is fine; values already in the environment win. Never printed.
  process.loadEnvFile(new URL('../.env', import.meta.url));
} catch {
  /* no .env: rely on the environment */
}

export const BASE_URL = process.env['E2E_BASE_URL'] ?? 'http://localhost:8080';
export const STRAPI_URL = process.env['E2E_STRAPI_URL'] ?? 'http://localhost:1337';

export default defineConfig({
  testDir: './e2e',
  testMatch: '**/*.spec.ts',
  // One worker, in file order: us-01-config-change adds and removes a published field, which the
  // other files must never see (they assert the exact field list).
  workers: 1,
  fullyParallel: false,
  retries: 0,
  forbidOnly: !!process.env['CI'],
  reporter: [['list'], ['html', { open: 'never' }]],
  use: {
    baseURL: BASE_URL,
    locale: 'es-CO',
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
});

